entries[22910] = { ["name"] = "Feuerbrandfalle", ["text"] = "245 Mana\nSofort 15 sek. Abklingzeit\nEine Feuerfalle platzieren, die den ersten sich nähernden Feind für 690 Feuerschaden über 15 Sek. verbrennt. Die Falle besteht für 1 Min.. Fallen können nur außerhalb von Kampfaktivitäten platziert werden. Es kann immer nur jeweils eine Falle aktiv sein." }
