entries[22921] = { ["name"] = "Gurt der Einsicht", ["text"] = "Wirken in 1 min\nReagenzien:\nUnverwüstliches Leder (12), Mächtiges Mojo (12), Geschmeidiger unverwüstlicher Balg (2), Runenfaden (4)\nGurt der Einsicht\nWird beim Anlegen gebunden\nTaille Leder\n98 Rüstung\n+9 Ausdauer\n+23 Intelligenz\nHaltbarkeit 35 / 35\n57" }
