entries[22926] = { ["name"] = "Chromatischer Umhang", ["text"] = "Wirken in 1 min\nReagenzien:\nUnverwüstliches Leder (30), Glänzende chromatische Schuppe (12), Schwarze Drachenschuppe (30), Rote Drachenschuppe (30), Geschmeidiger unverwüstlicher Balg (5), Runenfaden (8)\nChromatischer Umhang\nWird beim Anlegen gebunden\nRücken\n48 Rüstung\n+10 Ausdauer\n+9 Feuerwiderstand\n+9 Schattenwiderstand\n57\nAnlegen: Erhöht Eure Chance, einen kritischen Treffer durch Zauber zu erzielen, um 1%." }
entries[22927] = { ["name"] = "Balg der Wildnis", ["text"] = "Wirken in 1 min\nReagenzien:\nUnverwüstliches Leder (30), Essenz des Lebens (12), Essenz des Wassers (10), Larvensäure (8), Geschmeidiger unverwüstlicher Balg (3), Runenfaden (8)\nBalg der Wildnis\nWird beim Anlegen gebunden\nRücken\n48 Rüstung\n+8 Ausdauer\n+10 Intelligenz\n57\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 42." }
